const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([177.51, 64.73]); // Onemen Bay near Anadyr
  const region = point.buffer(1000); // 1km buffer
  const date1 = '2025-08-09';
  const date2 = '2025-09-11';
  const window = 15; // days around target date

  // Function to get Sentinel-2 image for a target date
  function getS2Image(targetDate) {
    const start = ee.Date(targetDate).advance(-window, 'day');
    const end = ee.Date(targetDate).advance(window, 'day');
    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(start, end)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

    // Cloud masking function
    function maskS2Clouds(image) {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    }

    col = col.map(maskS2Clouds);
    // Get image closest to target date
    const sorted = col.sort('system:time_start', false);
    const image = sorted.first();
    return image;
  }

  // Function to calculate NDVI and stats
  function processImage(img, dateStr) {
    // Check if image exists
    const imgId = img.id();
    const count = img.bandNames().length();
    const hasBands = count.getInfo();
    if (hasBands === 0) {
      return { ndvi: null, pixels: 0, date: dateStr, valid: false };
    }

    // Calculate NDVI (B8: NIR, B4: Red)
    const ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI');

    // Get pixel count and mean
    const stats = ndvi.reduceRegion({
      reducer: ee.Reducer.count().combine({
        reducer2: ee.Reducer.mean(),
        sharedInputs: true
      }),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    });

    const pixelCount = ee.Number(stats.get('NDVI_count')).getInfo();
    const meanNdvi = ee.Number(stats.get('NDVI_mean')).getInfo();

    return {
      ndvi: meanNdvi,
      pixels: pixelCount,
      date: dateStr,
      valid: pixelCount > 0 && meanNdvi !== null
    };
  }

  // 2. Data Acquisition & Check
  console.log('Checking data availability...');

  const img1 = getS2Image(date1);
  const img2 = getS2Image(date2);

  const result1 = processImage(img1, date1);
  const result2 = processImage(img2, date2);

  // Print stats
  console.log(`${date1}: NDVI=${result1.ndvi !== null ? result1.ndvi.toFixed(3) : 'No data'}, Valid pixels=${result1.pixels}`);
  console.log(`${date2}: NDVI=${result2.ndvi !== null ? result2.ndvi.toFixed(3) : 'No data'}, Valid pixels=${result2.pixels}`);

  // 3. Validation & Final Answer
  // Case C1: Empty Collection (no images)
  if (!result1.valid && result1.pixels === 0) {
    console.log('<answer>C1</answer>');
    return;
  }
  if (!result2.valid && result2.pixels === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Case C2: No Valid Pixels
  if (result1.pixels === 0 || result2.pixels === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Case C3: Calculation Failure
  if (result1.ndvi === null || result2.ndvi === null || 
      isNaN(result1.ndvi) || isNaN(result2.ndvi) ||
      result1.ndvi < -1 || result1.ndvi > 1 ||
      result2.ndvi < -1 || result2.ndvi > 1) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Valid comparison
  if (result1.ndvi > result2.ndvi) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
